from pathlib import Path
import json,html,re,hashlib
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[2]
plan=json.loads((ROOT/'.agents/workflows/slide_plan.json').read_text(encoding='utf-8'))['slides']
cards={json.loads(p.read_text(encoding='utf-8'))['card_id']:json.loads(p.read_text(encoding='utf-8')) for p in (ROOT/'cards').glob('CARD-*.json')}
DOIS={'P01':'https://doi.org/10.3390/geomatics5030027','P02':'https://doi.org/10.1016/j.rse.2019.05.024','P03':'https://doi.org/10.1038/s41597-022-01878-2','P04':'https://doi.org/10.3390/rs16234583','P05':'https://doi.org/10.1016/j.rse.2024.114122'}
# Content is an explanatory paraphrase grounded in each slide's linked Wiki entries.
LESSONS=[
('先看懂衛星影像中的雲與陰影','你會學會辨識四類像元、理解規則式與 AI 分割，以及判讀評估指標。',['我們想要的是可信的「清晰像元」，而不只是漂亮的影像。','每一頁都可以查看原始 Wiki 條目與論文來源。'],'這份簡報是文獻知識教學，不會執行任何雲偵測模型。'),
('雲遮住地表，雲影改變亮度','光學衛星的觀測常被雲遮擋；雲影讓地表變暗，可能干擾分類和變遷分析。',['雲：改變或遮蔽地表回傳的光譜訊號。','雲影：遮擋入射日光，使下方像元變暗。','雲影辨識的目的先是標示受污染像元，並非恢復看不見的地表。'],'當影像被雲遮蔽時，「偵測雲」不等於「還原真實地物」。'),
('多個波段，觀察同一個地方','光學遙測不只有 RGB。可見光、近紅外與短波紅外提供互補資訊。',['RGB：人眼較容易理解的彩色組合。','NIR：近紅外資訊；SWIR：短波紅外資訊。','不同衛星的波段數量與解析度不同，演算法需要考慮這些差異。'],'Sentinel-2 的不同波段具有 10、20、60 m 的不同解析度。'),
('四類像元，不只「有雲／沒雲」','CloudSEN12 使用 Clear、Thick Cloud、Thin Cloud、Cloud Shadow 四類標籤。',['Clear：無雲及雲影污染的像元。','Thick Cloud：遮蔽地表的厚雲。','Thin Cloud：仍可能看見背景，但光譜已改變。','Cloud Shadow：厚雲或薄雲投射的暗區。'],'厚薄雲沒有跨所有資料集都一致的定量界線；先看採用的標註規則。'),
('暗的地方不一定是雲影','雲影與地形陰影在光學影像都可能看起來很暗，但成因並不相同。',['雲影要考慮雲的位置與太陽幾何。','地形陰影與山坡坡度、坡向及照明方向有關。','Fmask 類方法利用光譜、雲影投影關係以及 DEM 等資訊降低誤判。'],'水體、深色岩石也可能被誤判為雲影。'),
('光譜資訊像多把不同的尺','利用 RGB、NIR、SWIR 等不同波段組合，可以提升判釋的資訊量。',['單一亮度門檻容易把雪、亮屋頂等誤當成雲。','Sentinel-2 含多個不同解析度的光譜波段。','影像若只有 RGB，不代表能直接沿用需要額外波段的演算法。'],'本頁色帶是波段概念示意，不代表真實感測器光譜曲線。'),
('Fmask 4.0：由規則到遮罩','Fmask 4.0 結合光譜閾值、輔助地理資料、雲機率與雲影幾何推估。',['輸入 TOA 反射率及 GSWO、DEM 等輔助資訊。','計算潛在雲與雪／冰等候選像元。','用雲與太陽的幾何關係尋找可能雲影。','輸出雲、雲影等遮罩，仍可能發生漏判或誤判。'],'Fmask 並非深度學習模型；其不同感測器版本的輸入條件也不相同。'),
('AI：幫影像中每個像元貼標籤','語意分割（Semantic Segmentation）讓模型對每一個像元輸出類別。',['訓練資料提供輸入影像及參考標籤。','CNN 或 Encoder–Decoder 網路學習空間與光譜特徵。','模型輸出遮罩，仍需要透過獨立測試資料評估。'],'AI 表現與訓練資料、感測器、雲型及測試方式相關。'),
('U-Net 與 CloudS2Mask','U-Net 採編碼器–解碼器架構；CloudS2Mask 結合 U-Net 與 RegNetY_006。',['先使用三類資料學習，再遷移學習到四類標籤。','逐步調整影像尺寸（Progressive Resizing）。','可用集成與測試時增強改善表現，但會增加成本。'],'這是論文所描述的模型，不代表本作業已重新訓練或執行。'),
('把同一張影像換成不同遮罩','雲影遮罩可以是二元，也可以是多類別；兩者定義必須說清楚。',['二元遮罩可能只標「雲／非雲」，也可能將雲影合併為污染類。','多類別遮罩可以分別保留厚雲、薄雲、雲影及清晰像元。','大型場景可切為 patches 推論，但切塊邊界需要仔細合併。'],'下方互動為人工繪製的概念圖，不是模型推論，也不是實際衛星照片。'),
('不能只看一個 Accuracy','從混淆矩陣取得 TP、FP、FN、TN，再計算 Precision、Recall、F1、IoU 等指標。',['Precision：預測為目標類別的像元有多少真的屬於該類。','Recall：真實目標類別有多少被找出。','IoU：預測與真值的交集／聯集。','背景像元很多時，OA 可能掩蓋少數類別錯誤。'],'不同研究採用的 OA 與 BOA 並非同一指標。'),
('比較方法前，先比較條件','Fmask、CloudSEN12 與 CloudS2Mask 提供不同類型的研究證據，不能只挑最大的數字排名。',['Fmask 4.0 在自身 Sentinel-2 驗證資料中報告 OA 94.30%。','CloudS2Mask 在 CloudSEN12 測試集報告 cloud/no-cloud BOA 0.932（10 m、ME、7 ATTA）。','兩個數字的資料、任務與指標不同，不能直接當作孰優孰劣的證據。'],'請點選「查看知識來源」，核對每項數據的論文與條目。')]
assert len(LESSONS)==len(plan)==12
for s,(headline,lead,bullets,caveat) in zip(plan,LESSONS):
    s.update({'headline':headline,'lead':lead,'bullets':bullets,'caveat':caveat})
    s['cards']=[cards[f"CARD-S{s['number']:02d}-{i:02d}"] for i in range(1,len(s['wiki_ids'])+1)]
    assert [c['wiki_id'] for c in s['cards']]==s['wiki_ids']
    s['sources']=sorted(set(x for c in s['cards'] for x in c['source_ids']))
# DRAFTS
(ROOT/'drafts').mkdir(exist_ok=True)
for s in plan:
    out=[f"# Slide {s['number']:02d}｜{s['title']}",'',f"**教學目標：** {s['objective']}",'',f"## 主標題：{s['headline']}",'',s['lead'],'','## 教學重點']+[f'- {x}' for x in s['bullets']]+['','## 概念限制',s['caveat'],'','## 證據卡與 Wiki']+[f"- {c['card_id']} → {c['wiki_id']}；{c['source_pages']}" for c in s['cards']]+['','> 內容狀態：以 Wiki 為依據的教學改寫；數據來源已對照 Wiki，人工最終核准仍待完成。','']
    (ROOT/'drafts'/f"slide_{s['number']:02d}.md").write_text('\n'.join(out),encoding='utf-8')
# Store machine-readable slide data used by deterministic renderer
payload={'schema':1,'status':'phase4_draft_pending_human_approval','sources':DOIS,'slides':plan}
(ROOT/'assets').mkdir(exist_ok=True)
(ROOT/'assets'/'slide_content.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
# renderer: data embedded so local file:// works; intentionally no remote dependencies
json_data=json.dumps(payload,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
